import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.B3amng90.js";const o="/abu-aigc-guide/screenshots/marketing.webp",s="/abu-aigc-guide/screenshots/marketing-remix.webp",h=JSON.parse('{"title":"爆款：为商品制作短视频","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/marketing.md","filePath":"workflows/marketing.md"}'),n={name:"workflows/marketing.md"};function l(g,a,c,m,p,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="爆款-为商品制作短视频" tabindex="-1">爆款：为商品制作短视频 <a class="header-anchor" href="#爆款-为商品制作短视频" aria-label="Permalink to &quot;爆款：为商品制作短视频&quot;">​</a></h1><p>进入侧栏 <strong>爆款</strong>，围绕商品图片、卖点或参考内容制作短视频脚本与镜头素材。</p><h2 id="准备商品资料" tabindex="-1">准备商品资料 <a class="header-anchor" href="#准备商品资料" aria-label="Permalink to &quot;准备商品资料&quot;">​</a></h2><ol><li>选择 <strong>创意</strong>，让系统围绕商品生成新脚本；或选择 <strong>复刻</strong>，根据参考内容整理相近的节奏和结构。</li><li>上传同一商品的 <strong>1–4 张商品图</strong>。也可以添加支持的平台链接作为参考，或按需上传模特图。参考视频是否可用取决于当前模型。</li><li>在商品描述中填写准确的品类、功能、材质和卖点。不要把 AI 推测出的信息当成已经核实的商品事实。</li><li>选择投放平台和创意角度，检查页面列出的生成参数。</li></ol><p><a href="/abu-aigc-guide/screenshots/marketing.webp"><img src="'+o+'" alt="爆款创意模式的商品图、模特图、商品描述和投放平台入口" loading="lazy"></a></p><p><em>用「创意」从商品资料开始写脚本。点击截图可查看大图。</em></p><p><a href="/abu-aigc-guide/screenshots/marketing-remix.webp"><img src="'+s+'" alt="爆款复刻模式的参考链接和素材区" loading="lazy"></a></p><p><em>用「复刻」沿用参考内容的节奏和结构。</em></p><h2 id="检查脚本并生成" tabindex="-1">检查脚本并生成 <a class="header-anchor" href="#检查脚本并生成" aria-label="Permalink to &quot;检查脚本并生成&quot;">​</a></h2><ol><li>点击 <strong>写脚本</strong>，等待商品信息和分镜脚本生成。</li><li>逐段检查商品外观、卖点、镜头节奏、字幕和旁白，修正不准确或不符合品牌要求的部分。</li><li>确认视频模型和参数后，先生成少量镜头检查效果，再继续完成视频。</li><li>复核生成结果中的商品细节、文案和人物动作。发布前检查平台规范与素材授权。</li></ol><p>如果 <strong>写脚本</strong> 按钮不可用，先确认已上传商品图且上传完成，并检查是否选中了可用的视频模型。仍无法提交时，请联系服务支持。</p>',11)])])}const u=e(n,[["render",l]]);export{h as __pageData,u as default};
